QB.add(50,[{"n":1,"q":"The patient presented with stroke-like symptoms. Cerebral angiography done revealed the following finding. Which among the following is false regarding this condition?","o":[{"t":"Involves occlusion of predominantly large arteries"},{"t":"Associated with vascular inflammation"},{"t":"Anticoagulation is contraindicated"},{"t":"More common in young adults"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Associated with vascular inflammation"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"Cerebral angiography shows a “Puff of smoke” appearance which is suggestive of Moyamoya disease ."},{"k":"b","l":0,"v":"Moyamoya disease is a rare “Non-Inflammatory” neurological disorder characterized by occlusion predominantly involving large arteries."},{"k":"p","l":0,"v":"Moyamoya disease:"},{"k":"p","l":1,"v":"Description Isolated chronic, non-inflammatory (Option B) usually"},{"k":"p","l":2,"v":"bilateral vasculopathy of undetermined etiology characterized by progressive narrowing of large arteries (Option A) - distal part of internal carotid artery (ICA) , stem of middle cerebral (MCA) and anterior cerebral artery (ACA)"},{"k":"p","l":1,"v":"Etiology Genetic: MYMY genes involved"},{"k":"p","l":2,"v":"Drugs: Phenylpropanolamine, Cocaine, Methamphetamine Idiopathic: exact cause unknown"},{"k":"p","l":1,"v":"Pathogenesis Chronic occlusion of large arteries leads to development"},{"k":"p","l":2,"v":"of collaterals usually involving lenticulostriate branches - gives rise to “Puff of smoke” appearance on angiography. Vascular inflammation is absent ."},{"k":"p","l":1,"v":"Clinical present More commonly affects Younger adults (Option C) , ation usually Asians ."},{"k":"p","l":2,"v":"Can present with both Ischaemic - secondary to occlusion (pediatric age group) and Hemorrhagic - secondary to burst of collaterals (adult age group) stroke-like presentation ."},{"k":"img","v":7642},{"k":"p","l":1,"v":"Diagnosis"},{"k":"p","l":2,"v":"... (content truncated)"},{"k":"p","l":1,"v":"Management Medical Management:"},{"k":"p","l":2,"v":"Aspirin 50-100mg: for maintenance Anticoagulation: is usually contraindicated (Option C) as risk of collaterals induced hemorrhage can occur. Surgical Management: Revascularization procedures usually using superficial temporal artery bypass may be beneficial."}],"qi":[7542]},{"n":2,"q":"What is the most likely diagnosis on the basis of the MRI image given below?","o":[{"t":"Vestibular schwannoma"},{"t":"Pneumocephalus"},{"t":"Craniopharyngioma"},{"t":"Prion disease"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) Vestibular schwannoma"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Vestibular schwannoma /Acoustic neuroma/vestibular schwannoma/neurilemmoma/eighth nerve tumor- benign, encapsulated, extremely slow growing tumor of the VIIIth cranial nerve shows ice cream cone appearance."},{"k":"p","l":0,"v":"Below image depicts vestibular schwannoma:"},{"k":"p","l":0,"v":"Vestibular schwannoma\" data-author=\"\" data-hash=\"9192\" data-license=\"\" data-source=\"\" data-tags=\"April2025\" src=\"https://image.prepladder.com/notes/7Ih55L7jwg6aEVGcYezN174436 0157.png\" /> Below image depicts ice cream cone sign:"},{"k":"p","l":0,"v":"cone sign\" data-author=\"\" data-hash=\"9193\" data-license=\"\" data-source=\"\" data-tags=\"April2025\" src=\"https://image.prepladder.com/notes/IatwQHujHIleopzBT9JP1744360 261.png\" /> MRI findings:"},{"k":"b","l":0,"v":"Typically appears as an oval or round mass."},{"k":"b","l":0,"v":"Target Sign- central area of hypointensity surrounded by a peripheral area of hyperintensity."}],"qi":[7548]},{"n":3,"q":"What is the most likely diagnosis on the basis of the CT image given below?","o":[{"t":"Pantothenate kinase-associated neurodegeneration"},{"t":"Pneumocephalus"},{"t":"Craniopharyngioma"},{"t":"Prion disease"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) Pantothenate kinase-associated neurodegeneration"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Pantothenate kinase-associated neurodegeneration (PKAN) (aka Halloverdan spatz disease):"},{"k":"b","l":0,"v":"A rare autosomal recessive neurodegenerative disorder marked by the accumulation of iron in the brain's nuclei."},{"k":"b","l":0,"v":"Characterized by progressive extrapyramidal dysfunction and dementia"},{"k":"p","l":0,"v":"Brain MRI shows characteristic radiologic sign known as the \"eye of the tiger\""},{"k":"img","v":7648}],"qi":[7553]},{"n":4,"q":"Which of the following is a CT finding of Pneumocephalus?","o":[{"t":"Mount Fuji Sign"},{"t":"Air Bubble Sign"},{"t":"Peaking Sign"},{"t":"All of the above"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) All of the above"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"CT findings:"},{"k":"p","l":0,"v":"Sign Observation"},{"k":"img","v":7654},{"k":"p","l":0,"v":"Mount Fuji Sign (Option A ruled out)"},{"k":"p","l":2,"v":"... (content truncated)"},{"k":"img","v":7659},{"k":"p","l":0,"v":"Air Bubble Sign (Option B ruled out)"},{"k":"p","l":2,"v":"... (content truncated)"},{"k":"img","v":7664},{"k":"p","l":0,"v":"Peaking Sign (Option C ruled out)"},{"k":"p","l":2,"v":"... (content truncated)"}]},{"n":5,"q":"Describe the lesion given in the MRI below:","o":[{"t":"Cystic"},{"t":"Heterogenous"},{"t":"Homogenous"},{"t":"Both A and B"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) Both A and B"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Given image is an MRI of Craniopharyngioma"},{"k":"p","l":0,"v":"Craniopharyngiomas are uncommon, benign tumors of the central nervous system."},{"k":"p","l":0,"v":"Craniopharyngioma Appearance in MRI:"},{"k":"b","l":0,"v":"Cystic area"},{"k":"b","l":0,"v":"Heterogeneous in texture"},{"k":"b","l":0,"v":"Combination of solid, cystic, and calcification components"}],"qi":[7559]},{"n":6,"q":"Which of the following is false on findings of Creutzfeldt-Jakob disease?","o":[{"t":"Periodic sharp wave complexes on EEG"},{"t":"Cortical ribboning in MRI"},{"t":"Increased intensity in the basal ganglia"},{"t":"All prion diseases are characterized by spongiform changes"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) All prion diseases are characterized by spongiform changes (vacuolisation inside cells)"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"FFI (Fatal familial insomnia) a type of prion disease does not show this change"},{"k":"p","l":0,"v":"All of the findings are true in case of Creutzfeldt-Jakob disease (CJD.)"},{"k":"p","l":0,"v":"It is a rare, fatal degenerative brain disorder caused by prion proteins."},{"k":"p","l":0,"v":"Creutzfeldt-Jakob disease (CJD) findings:"},{"k":"img","v":7671},{"k":"p","l":1,"v":"Electroencephalography (EEG)"},{"k":"p","l":2,"v":"Periodic sharp wave complexes (PSWC) (Option A ruled out) These can be either lateralized in earlier stages or generalized in later stages."},{"k":"img","v":7676},{"k":"p","l":1,"v":"MRI findings"},{"k":"p","l":2,"v":"... (content truncated)"},{"k":"img","v":7681}]},{"n":7,"q":"A 35-year-old male presents to the ER after a fall, initially conscious but rapidly deteriorates following a brief lucid interval. The CT image is given below. What is the diagnosis?","o":[{"t":"Epidural hematoma"},{"t":"Extradural hematoma"},{"t":"Subdural hematoma"},{"t":"Intracerebral hematoma"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) Epidural hematoma"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Given CT shows biconvex mass which is present in epidural hematoma."},{"k":"p","l":0,"v":"CT findings:"}],"qi":[7565]},{"n":8,"q":"Based on the MRI finding (shown below) , Which of the following criteria and corresponding treatment used in this condition?","o":[{"t":"Brighton’s criteria, IV Steroids"},{"t":"Brighton’s criteria, IV Immunoglobulin"},{"t":"McDonald’s criteria, IV Steroids"},{"t":"McDonald’s criteria, IV Immunoglobulin"}],"a":[2],"s":[{"k":"p","l":0,"v":"Correct answer: C) McDonald’s criteria, IV Steroids"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"MRI shows Dawson’s fingers , characteristic finding in Multiple Sclerosis (MS) ."},{"k":"b","l":0,"v":"Criteria used is McDonald’s criteria and IV Methylprednisolone (Steroid) is the treatment of choice in MS."},{"k":"p","l":0,"v":"Multiple Sclerosis:"},{"k":"p","l":1,"v":"Description Chronic neurological disorder characterized by"},{"k":"p","l":2,"v":"inflammation, demyelination and sclerosis with lesions disseminated over time and space"},{"k":"p","l":1,"v":"Pathogenesi Autoimmune cause: s Triggering antigen: Myelin basic protein"},{"k":"p","l":2,"v":"Antibodies target: Oligodendrocytes"},{"k":"p","l":1,"v":"Clinical U/L Optic neuritis: Positive Uhthoff sign (blurring of features vision on heat exposure)"},{"k":"p","l":2,"v":"Sensory: Positive Lhermitte sign (Flexion at neck fi Paraesthesia /shock-like sensation across the spine/back)"},{"k":"img","v":7685},{"k":"p","l":1,"v":"Types"},{"k":"p","l":2,"v":"... (content truncated)"},{"k":"p","l":1,"v":"Scoring Extended disability scoring scale (EDSS) scale"},{"k":"img","v":7571},{"k":"p","l":1,"v":"Diagnosis"},{"k":"p","l":2,"v":"Criteria: McDonald’s criteria (Option C) MRI: Dawson’s fingers (demyelination over periventricular areas); lesions dissemination over time & space seen. ... (content truncated)"},{"k":"p","l":1,"v":"Treatment Acute: IV Methylprednisolone (Option C)"},{"k":"p","l":2,"v":"Disease modifying drugs: Ocrelizumab (anti-CD20) > Natalizumab >> Mitoxantrone. Other drugs: IFN-b: least side effects and hence more preferred in chronic disease Fingolimod: SIP-1 Modulator Gatiramer acetate: Polypeptide drug Dimethyl fumarate: Krebs cycle metabolite Miscellaneous : Daclizumab, Almetuzumab, Mitoxantrone"},{"k":"p","l":0,"v":"Brighton criteria (Option B): Used for Gullaine barre syndrome (GBS) and treatment of choice is IVIg (Immunoglobulin)."}],"qi":[7571]},{"n":9,"q":"A 13 year old male patient presented with complaints of poor scholastic performance, history of recurrent seizures since infancy and the following incidental finding on his back. What does the incidental finding denote and probable diagnosis of this patient?","o":[{"t":"Neurofibroma and Neurofibromatosis"},{"t":"Adenoma sebaceum and Tuberous sclerosis"},{"t":"Shagreen patch and Tuberous sclerosis"},{"t":"Cafe-au-lait spots and Neurofibromatosis"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer : C) Shagreen patch and Tuberous sclerosis"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The given clinical scenario of an adolescent male patient with complaints of poor scholastic performance ( low IQ ), history of recurrent seizures since infancy and clinical image showing shagreen patch suggests a probable diagnosis of tuberous sclerosis."},{"k":"p","l":1,"v":"Tuberous sclerosis (BOURNEVILLE DISEASE)"},{"k":"p","l":1,"v":"Pathophysiology It is an autosomal dominant disorder."},{"k":"p","l":2,"v":"Genes involved are TSC1 in chromosome 9 producing hamartin protein and TSC2 is on chromosome 16 producing tuberin protein . Both these proteins play a role in cell growth and cell division. Mutations lead to aberrant activation of mTOR pathway signalling giving rise to various tumours."},{"k":"p","l":1,"v":"Clinical features Classical triad of seizures (epilepsy), low IQ, facial"},{"k":"p","l":2,"v":"angiofibromas ( adenoma sebaceum )- EPILOIA Other skin manifestations include shagreen patches, hypomelanotic macules ( Ash leaf macules ), periungual fibromas ( Koenen tumours ) Associated with renal angiomyolipomas , cardiac rhabdomyomas (in children) Increased risk of subependymal nodules, cortical tubers and subependymal giant cell astrocytomas (SEGAs)"},{"k":"p","l":1,"v":"Treatment Anticonvulsants for seizures"},{"k":"p","l":2,"v":"mTOR inhibitors (sirolimus or everolimus) for SEGAs and seizure reduction"},{"k":"img","v":7691},{"k":"img","v":7697},{"k":"img","v":7702},{"k":"p","l":0,"v":"Adenoma sebaceum and Tuberous sclerosis (Option B): It is incorrect since the image shows a shagreen patch and not adenoma sebaceum."},{"k":"p","l":0,"v":"Neurofibroma and Neurofibromatosis (Options A) and Cafe-au-lait spots and Neurofibromatosis (Option D):"},{"k":"b","l":0,"v":"Neurofibromas and cafe-au-lait spots are associated with neurofibromatosis ."},{"k":"b","l":0,"v":"They are also associated with seizures but do not show shagreen patches. {{caption_text}}"},{"k":"img","v":7707},{"k":"img","v":7713}],"qi":[7576]},{"n":10,"q":"A 30 year old female who delivered a male baby via C-section owing to eclampsia developed a sudden onset headache, seizures, visual disturbances and altered sensorium 2 days following delivery. MRI showed the following (shown below). What is the likely diagnosis? (CADASIL - Cerebral Autosomal Dominant Arteriopathy with Subcortical Infarcts and Leukoencephalopathy)","o":[{"t":"Reversible cerebral vasoconstriction syndrome (RCVS)"},{"t":"CADASIL"},{"t":"Postpartum transient ischemic attack"},{"t":"Posterior reversible encephalopathy syndrome (PRES)"}],"a":[3],"s":[{"k":"p","l":0,"v":"Correct answer: D) Posterior reversible encephalopathy syndrome (PRES)"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Postpartum female with history of eclampsia during antenatal/intrapartum period presenting with sudden onset headache and other focal neurological deficits is suggestive of Posterior Reversible Encephalopathy Syndrome (PRES) . MRI reveals hyperintensities over the occipital (posterior) lobe ."},{"k":"p","l":0,"v":"Posterior Reversible Encephalopathy Syndrome (PRES):"},{"k":"p","l":1,"v":"Introduction Neurological disorder characterized by posterior lobe"},{"k":"p","l":2,"v":"involvement resulting in sudden onset neurological manifestations"},{"k":"p","l":1,"v":"Etiology Hyperperfusion state fi Cerebral edema"},{"k":"p","l":2,"v":"Pre-eclampsia /Eclampsia in the postpartum period Uncontrolled hypertension Drugs: Sympathomimetics (Amphetamine), Cytotoxic (anti-cancer) Renal: AKI, Nephrotic syndrome Autoimmune: SLE, APLA syndrome"},{"k":"p","l":1,"v":"Clinical presenta Usually manifests within a week in the postpartum phase tion Sudden onset headache, seizures."},{"k":"p","l":2,"v":"Visual disturbances, altered mentation and other focal neurological deficits Rarely can present with ischaemic symptoms (if present for long duration)"},{"k":"p","l":1,"v":"Diagnosis MRI: Hyperintensities + over occipital lobe (and hence"},{"k":"p","l":2,"v":"the name posterior) occipital lobe\" data-author=\"Rashmi Chawla, Daniel Smith and Paul E Marik\" data-hash=\"9162\" data-license=\"CC BY SA 3.0\" data-source=\"https://en.m. wikipedia.org/wiki/File:Posterior_reversible_encephalopa thy_syndrome_MRI.jpg\" data-tags=\"April2025\""},{"k":"p","l":2,"v":"qDAAKxhVb41744358205.png\" />"},{"k":"p","l":1,"v":"Management Anti-hypertensives: first step is to control BP (Target"},{"k":"p","l":2,"v":"MAP: 130 mmHg) Anti-epileptics: if seizures +"},{"k":"p","l":1,"v":"Prognosis Good prognosis, only supportive care required"},{"k":"p","l":2,"v":"Manifestations are reversible"},{"k":"p","l":1,"v":"Differential Reversible cerebral vasoconstriction syndrome (RCVS): diagnosis (Option A)"},{"k":"p","l":2,"v":"Presentation: sudden onset severe headache (similar to SAH) Ischemic/hemorrhagic stroke -like presentation Severe new-onset hypertension is usually present Angiography: Non-inflammatory diffuse vascular changes involving all lobes (resembles vasculitis) Treatment: Oral CCBs ; recurrence-rare"},{"k":"p","l":0,"v":"CADASIL (Option B): Presents in the 5th-6th decade with stroke-like symptoms (small vessel syndrome). Lack of associated features like Migraine with aura , dementia makes this diagnosis unlikely."},{"k":"p","l":0,"v":"Postpartum transient ischemic attack (TIA) (Option C): Usually symptoms last < 1 hour (definition: < 24 hours) , although sudden onset headache with altered mentation makes TIA less likely."}],"qi":[7582]},{"n":11,"q":"Which among the following statements is/are false regarding CADASIL disorder? 1) Autosomal Dominant inheritance 2) Predominantly causes Large-vessel stroke 3) Characteristic symptom is Migraine with aura 4) Notch-3 gene is involved","o":[{"t":"Only 2"},{"t":"1,3"},{"t":"1,2"},{"t":"2,3"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) Only 2"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"CADASIL - Cerebral Autosomal Dominant Arteriopathy with Subcortical Infarcts and Leukoencephalopathy is an inherited disorder characterized by small-vessel strokes."},{"k":"p","l":0,"v":"CADASIL (Cerebral Autosomal Dominant Arteriopathy with Subcortical Infarcts and Leukoencephalopathy):"},{"k":"p","l":1,"v":"Description Inherited disorder characterized by small-vessel strokes"},{"k":"p","l":2,"v":"(Statement-2)"},{"k":"p","l":1,"v":"Etio- pathogenesis Notch-3 gene (Statement-4)"},{"k":"p","l":2,"v":"Autosomal Dominant inheritance (Statement-1) Notch-3 gene regulates Epidermal growth factor (EGF)"},{"k":"p","l":1,"v":"Clinical features Age: 4th-5th decade"},{"k":"p","l":2,"v":"Small-vessel stroke Progressive dementia Migraine with aura: characteristic feature (Statement-3)"},{"k":"p","l":1,"v":"Diagnosis MRI: Extensive symmetric white matter changes over"},{"k":"p","l":2,"v":"anterior temporal lobe"}]},{"n":12,"q":"A 35 year old woman presents with a headache, seizures and focal neurological deficits. She has a history of oral contraceptive use. MRI venography reveals a filling defect in the cerebral venous sinus as shown in picture below. What is the most appropriate initial treatment for this patient?","o":[{"t":"Endovascular thrombolysis"},{"t":"Heparin anticoagulation"},{"t":"Oral warfarin immediately"},{"t":"Blood pressure management for hypotension"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Heparin anticoagulation"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"The initial treatment for cerebral venous thrombosis (CVT) is anticoagulation with heparin followed by warfarin."},{"k":"b","l":0,"v":"Anticoagulation helps prevent further clot formation and promotes recanalization."},{"k":"b","l":0,"v":"Endovascular thrombolysis (Option A) : Reserved for cases where anticoagulation fails or is contraindicated."},{"k":"b","l":0,"v":"Oral warfarin immediately (Option C): Warfarin is used after heparin therapy, not as the initial treatment (effect takes a few days to develop so cannot be used for immediate anticoagulation, also it increases coagulation initially)."},{"k":"p","l":0,"v":"Blood pressure management for hypotension (Option D): Hypotension is not a common trigger for CVT and is not the primary treatment."}],"qi":[7588]},{"n":13,"q":"A 75 year old male patient came to the OPD with complaints of recent onset stooping, broad based abnormal gait, short-term memory loss and urge incontinence. On radiological investigation, the following image is obtained. What is the probable diagnosis?","o":[{"t":"Parkinson’s disease"},{"t":"Alzheimer’s disease"},{"t":"Normal pressure hydrocephalus"},{"t":"Idiopathic intracranial hypertension"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer : C) Normal pressure hydrocephalus"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The given clinical scenario of an elderly male patient with complaints of recent onset stooping, broad based abnormal gait ( gait apraxia/ gait instability ), short term memory loss ( dementia ) and urge incontinence and on radiological investigation the image shows bilateral lateral ventriculomegaly which is suggestive of normal pressure hydrocephalus."},{"k":"p","l":0,"v":"Normal pressure hydrocephalus"},{"k":"b","l":0,"v":"It is also called Hakims–Adams syndrome which is seen usually in the elderly above 60 years of age with the classical triad of urinary incontinence, dementia and gait instability ( wet,wacky and wobbly )."},{"k":"b","l":0,"v":"Shuffling gait with preserved arm swing in NPH (Arm swing lost in Parkinsonism)"},{"k":"b","l":0,"v":"Other key features include bilateral ventriculomegaly and usually a normal CSF (6-28 cm of H 2 O) opening pressure although can be increased in some cases."},{"k":"b","l":0,"v":"Treatment includes shunt procedures such as ventriculo-peritoneal shunting."},{"k":"p","l":0,"v":"Parkinson’s disease (Option A): Although there is presence of a stooping gait in this case it does not denote a classical festinant gait seen in Parkinsonism. Other key features such as rigidity and tremors which are characteristic of Parkinson’s disease are also absent. Dementia in a case of Parkinson’s disease occurs usually after more than 1 year of Parkinson’s disease manifestations."},{"k":"p","l":0,"v":"Alzheimer’s disease (Option B): It is the most common cause of dementia which is usually inherited due to defective ubiquitin protein which helps in targeting and degradation of damaged neuronal protein . Another mechanism involved in the disease is due to decreased acetylcholine levels in the brain neurotransmission. Although short term memory loss is associated with Alzheimer’s; other clinical features and radiological imaging rules out its possible diagnosis."},{"k":"p","l":0,"v":"Idiopathic intracranial hypertension ( Option D):"},{"k":"p","l":1,"v":"Idiopathic intracranial hypertension"},{"k":"p","l":1,"v":"Pathophysiology It usually affects young obese women . Its exact cause"},{"k":"p","l":2,"v":"is uncertain, but obesity may impair CSF reabsorption, while certain medications like tetracycline and vitamin A are associated."},{"k":"p","l":1,"v":"Clinical features Patients typically present with headaches, diplopia , and"},{"k":"p","l":2,"v":"transient visual disturbances. Physical signs include papilloedema and possible sixth cranial nerve palsy ."},{"k":"p","l":1,"v":"Investigations Brain imaging to rule out structural causes ."},{"k":"p","l":2,"v":"Lumbar puncture, revealing elevated CSF pressure > 30 cmH2O."},{"k":"p","l":1,"v":"Treatment Weight loss might be beneficial."},{"k":"p","l":2,"v":"Medications such as acetazolamide or topiramate may lower intracranial pressure. Repeated lumbar punctures can alleviate headaches, but if vision is threatened, surgical options like optic nerve sheath fenestration or a lumbo-peritoneal shunt may be necessary."}],"qi":[7594]},{"n":14,"q":"A 30 year old male patient was brought to the casualty with a history of road traffic accident and sustained multiple injuries. On primary assessment, he was disoriented and complained of his worst and most painful headache he ever had. On CT brain imaging, the following image was seen. What is the most probable diagnosis in this patient?","o":[{"t":"Intracerebral hemorrhage"},{"t":"Subdural hemorrhage"},{"t":"Subarachnoid hemorrhage"},{"t":"Extradural hemorrhage"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Subarachnoid haemorrhage"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The most probable diagnosis in this patient is subarachnoid haemorrhage as the patient had a traumatic brain injury with the patient describing his headache as the worst headache he ever had (thunderclap headache) and CT brain findings suggestive of hyperdensities in bilateral sylvian cisterns and the basal cistern ."},{"k":"p","l":1,"v":"Subarachnoid haemorrhage"},{"k":"p","l":1,"v":"Etiology Most common cause is head injury ."},{"k":"p","l":2,"v":"Most common non-traumatic cause is due to saccular (berry) aneurysms , often at the circle of Willis - most commonly anterior communicating artery . Other causes include non-aneurysmal (perimesencephalic) haemorrhages, arteriovenous malformations and vertebral artery dissection. Increased risk in cases of polycystic kidney disease , and connective tissue disorders (e.g., Ehlers-Danlos syndrome )."},{"k":"p","l":1,"v":"Clinical features Sudden, severe \" thunderclap \" headache (often"},{"k":"p","l":2,"v":"occipital ), lasting hours to days. Often occurs during physical exertion or straining. Signs of raised ICP - vomiting, raised blood pressure, neck stiffness/pain, potential loss of consciousness, photophobia and neck stiffness (which may develop over time). Focal neurological signs may be present if associated intracerebral haematoma occurs."},{"k":"p","l":1,"v":"Investigations CT brain and lumbar puncture are essential for"},{"k":"p","l":2,"v":"diagnosis. CT can confirm SAH, but negative results do not exclude it (small blood volumes may not be detected). Lumbar puncture should be performed 12 hours post-symptom onset to detect xanthochromia . If SAH is confirmed, cerebral angiography is necessary to plan for treatment."},{"k":"p","l":1,"v":"Treatment Nimodipine (30–60 mg IV for 5–14 days , followed by"},{"k":"p","l":2,"v":"360 mg orally for 7 days) is used to prevent delayed ischemia. Aneurysms may be treated with endovascular coiling or surgical clipping to reduce bleeding risk. Management of complications includes drainage for obstructive hydrocephalus, vasodilators for delayed cerebral ischemia, and fluid restriction for hyponatremia. Other supportive measures for immobility-related complications (e.g., chest infection, venous thrombosis) may be necessary."},{"k":"p","l":0,"v":"Intracerebral haemorrhage (Option A), Subdural haemorrhage (Option B), Extradural haemorrhage (Option D): Worst headache of their life and the given CT imaging (blood in sylvian fissure) turns more towards SAH than others."}],"qi":[7599]},{"n":15,"q":"A 15 year old adolescent male patient came with his parents with complaints of neuropsychiatric symptoms such as tremors and an irritable mood. On physical examination, hepatomegaly and the following ophthalmological finding is seen. What is the probable diagnosis and gene involved in this patient?","o":[{"t":"Wilson’s disease and ATP7B gene"},{"t":"Hemochromatosis and HFE gene"},{"t":"Gilbert syndrome and UGT1A1 gene"},{"t":"Classical galactosemia and GALT gene"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) Wilson’s disease and ATP7B gene"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The given clinical scenario of an adolescent male with neuropsychiatric symptoms , hepatomegaly and ophthalmological finding of Kayser-Fleischer ring is suggestive of Wilson’s disease and the gene involved is ATP7B gene in chromosome 13 . (ATP 7A In menke kinky hair disease)"},{"k":"p","l":1,"v":"Wilson’s disease"},{"k":"p","l":1,"v":"Description Wilson's disease is caused by mutations in the ATP7B"},{"k":"p","l":2,"v":"gene, leading to defective copper excretion and increased copper accumulation in organs such as the liver, brain, and eyes , resulting in hepatolenticular degeneration."},{"k":"p","l":1,"v":"Clinical featur Hepatic : Jaundice, hepatomegaly, ascites; chronic liver es disease may develop by age 40 ."},{"k":"p","l":2,"v":"Neurological : Dysarthria, rigidity, tremors, uncoordinated handwriting. Psychiatric : Personality changes such as irritable mood, depression and anxiety. Ocular : Kayser-Fleischer rings (copper deposits in the Descemet’s membrane of cornea) and sunflower cataracts. Other : Delayed puberty, renal tubular dysfunction, skeletal issues (osteoporosis, rickets), hemolytic anemia."},{"k":"p","l":1,"v":"Investigations Biochemical : Low serum copper and ceruloplasmin ,"},{"k":"p","l":2,"v":"elevated hepatic transaminases, aminoaciduria, hemolytic anemia. Diagnostic Tests : Increased urinary copper excretion; liver biopsy for hepatic copper measurement (values >200 mg/g dry weight is definitive of Wilson’s disease)."},{"k":"p","l":1,"v":"Treatment Copper Chelation : D-penicillamine enhances urinary"},{"k":"p","l":2,"v":"copper excretion. Alternatives include trientine hydrochloride. Zinc Therapy : Reduces copper absorption in the gut mainly useful for presymptomatic patients and during pregnancy. Liver Transplantation : Considered in advanced cases or when medical therapy fails."},{"k":"p","l":0,"v":"Hemochromatosis (Option B):"},{"k":"b","l":0,"v":"Excessive iron absorption and deposition mainly in the liver, pancreas and heart tissues , leading to organ damage and failure."},{"k":"b","l":0,"v":"Clinical features include liver cirrhosis, diabetes, skin pigmentation (bronze diabetes ), arthritis, cardiomyopathy, and hypogonadotropic hypogonadism."},{"k":"p","l":0,"v":"Gilbert syndrome (Option C):"},{"k":"b","l":0,"v":"Most patients are asymptomatic but may experience chronic or recurrent jaundice, often triggered by illness, fasting, or stress."},{"k":"b","l":0,"v":"Mild symptoms like fatigue, nausea, anorexia, or abdominal pain may occur, but other liver functions remain normal."},{"k":"p","l":0,"v":"Classical galactosemia (Option D):"},{"k":"p","l":0,"v":"Untreated infants may face severe complications like cataracts, intellectual disability , and renal dysfunction , while even treated individuals can experience growth and developmental issues."}],"qi":[7606]},{"n":16,"q":"A 5 year old female child presented to the casualty with recurrent seizures and left sided hemiplegia. On physical examination, a reddish skin lesion was found since birth over the right side of her forehead involving the right eye, nose and cheek. On CT imaging of the brain, the following picture was seen. What is the probable diagnosis?","o":[{"t":"Von Hippel Lindau syndrome"},{"t":"Sturge Weber syndrome"},{"t":"Neurofibromatosis"},{"t":"Ataxia telangiectasia"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Sturge Weber syndrome"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"The given clinical scenario of a 5 year old female child with complaints of recurrent seizures , left sided hemiplegia with a description of port-wine stain in the right ophthalmic division of trigeminal nerve and a CT image showing the classical tram-track or rail-road sign suggests a diagnosis of Sturge Weber syndrome ."},{"k":"b","l":0,"v":"It is a sporadic disorder neurocutaneous syndrome characterised by a facial nevus or ‘port wine stain’ in the distribution of the ophthalmic division of the trigeminal nerve along with an ipsilateral ‘ rail road pattern/tram-track ’ of intracranial parallel cortical calcification and glaucoma."},{"k":"b","l":0,"v":"The major clinical manifestations include contralateral hemiplegia and intractable focal seizures which may lead to intellectual disability . Control of seizures may require surgery."},{"k":"p","l":0,"v":"Regular eye evaluation is necessary to monitor for glaucoma ."},{"k":"p","l":0,"v":"Von-Hippel Lindau syndrome (Option A):"},{"k":"b","l":0,"v":"Mutations (3p deletion) lead to numerous vascular tumours in the body such as clear cell carcinoma of the kidneys, cerebellar and retinal hemangioblastomas and spinal cord angiomas."},{"k":"b","l":0,"v":"Cerebellar signs and raised intracranial tension are the usual manifestations."},{"k":"p","l":0,"v":"Neurofibromatosis (Option C):"},{"k":"b","l":0,"v":"This is the most common type of neurocutaneous syndrome."},{"k":"b","l":0,"v":"There are two types: NF1 or von Recklinghausen disease caused by deletion of NF1 on chromosome 17, and NF2 (central NF), with NF2 located on chromosome 22."},{"k":"b","l":0,"v":"They also present with recurrent seizures but instead of port-wine stain, they show neurofibromas with nervous system abnormalities of optic glioma , intraspinal neurofibroma, aqueductal stenosis and dural ectasia ."},{"k":"p","l":0,"v":"Ataxia telangiectasia (Option D):"},{"k":"b","l":0,"v":"It usually presents with slowly progressive truncal ataxia starting in infancy."},{"k":"b","l":0,"v":"Choreoathetosis and oculomotor apraxia are usually seen."},{"k":"b","l":0,"v":"Skin manifestations start after the age of 2-3 years with cutaneous (at flexures) and ocular (bulbar conjunctiva) telangiectasia ."},{"k":"b","l":0,"v":"In addition, there is an immunodeficiency component leading to frequent sino-pulmonary infections and risk of lymphoreticular malignancies ."}],"qi":[7612]},{"n":17,"q":"A 65 year old male presents to the emergency department with a sudden onset of right sided weakness, slurred speech and facial drooping for the past hour. His vital signs are stable and his blood glucose level is within normal range. The attending physician suspects a stroke. What is the most appropriate initial imaging study to confirm the diagnosis and determine the type of stroke?","o":[{"t":"Magnetic Resonance Imaging (MRI)"},{"t":"Non-contrast Computed Tomography (CT)"},{"t":"CT Angiography (CTA)"},{"t":"Carotid Duplex Ultrasonography"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Non-contrast Computed Tomography (CT)"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"Non-contrast CT is the gold standard initial imaging modality for stroke evaluation in the acute setting."},{"k":"b","l":0,"v":"It is fast, widely available, and highly effective at distinguishing between ischemic and hemorrhagic stroke , which is critical for determining appropriate treatment."},{"k":"b","l":0,"v":"In ischemic stroke, the CT may be normal early on, but it rules out hemorrhage, which would contraindicate the use of thrombolytic therapy. Workup for stroke"},{"k":"p","l":1,"v":"Initial Assessment and Stabilization Upon arrival, ensure the ABCs (Airway, Breathing,"},{"k":"p","l":2,"v":"Circulation) are stable. Blood glucose levels should be checked quickly to address hypoglycemia or hyperglycemia."},{"k":"p","l":1,"v":"Determining Stroke Type: Imaging is A non-contrast CT scan is the primary imaging modality Key for differentiating between ischemic and hemorrhagic"},{"k":"p","l":2,"v":"strokes. Clinical features may suggest stroke type, but imaging is essential for confirmation as no clinical finding can definitively differentiate between the two."},{"k":"p","l":1,"v":"Further Investigations: Uncovering Detailed History and Physical Exam: Consider risk the Cause factors (hypertension, diabetes, smoking, atrial"},{"k":"p","l":2,"v":"fibrillation, etc.) and perform a neurological exam to localize the affected brain area. Laboratory Tests : Perform CBC, electrolytes, renal function, blood glucose, lipid profile, coagulation studies, ESR, and ECG (to detect arrhythmias and signs of recent MI)."},{"k":"p","l":1,"v":"Visualizing the Cerebral CT Angiography (CTA) : Assesses cerebral vasculature Vasculature: Imaging Techniques and identifies blockages/stenosis, but is performed after"},{"k":"p","l":2,"v":"non-contrast CT has ruled out hemorrhage (not for stroke type differentiation). (Option C ruled out) CT Perfusion Imaging : Assesses blood flow, identifying reduced perfusion and ischemic penumbra. MRI: Provides more detail but takes longer than CT and is not as widely available, thus not the first imaging choice for acute stroke evaluation. (Option A ruled out) MRA: Offers detailed images of blood vessels, similar to CTA. Cerebral Angiography: Gold standard for vessel evaluation , used when other techniques are inconclusive or before endovascular intervention. Ultrasound Techniques : Carotid Duplex Ultrasonography assesses carotid stenosis but is not a first-line acute imaging modality; Transcranial Doppler (TCD) measures blood flow velocity in intracranial arteries. (Option D ruled out)"},{"k":"p","l":1,"v":"Tailoring Investigations Based on Ischemic Stroke : Focuses on identifying the source of Stroke Type the blockage (cardioembolic, artery-to-artery embolic,"},{"k":"p","l":2,"v":"small vessel disease). Hemorrhagic Stroke: Investigations focus on identifying causes of bleeding (e.g., hypertension, aneurysm, vascular malformation)."}]},{"n":18,"q":"A 70 Y/O woman presents to the emergency department with sudden-onset slurred speech and right-sided facial weakness that resolved after 30 minutes. She has a history of hypertension and type 2 diabetes mellitus. Her blood pressure on arrival is 160/95 mmHg. She is otherwise stable and has no residual neurological deficits on examination. Based on the ABCD2 score, what is the total score for this patient, and how would her risk of stroke be classified?","o":[{"t":"Score 3, low risk"},{"t":"Score 4, moderate risk"},{"t":"Score 5, moderate risk"},{"t":"Score 6, high risk"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) Score 6, high risk"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"ABCD2 score"},{"k":"b","l":0,"v":"Clinical tool used to predict the risk of stroke following a transient ischemic attack (TIA)."},{"k":"b","l":0,"v":"It helps stratify patients into different risk categories to determine the likelihood of having a stroke in the short term (usually within 48 hours to 7 days after a TIA)."},{"k":"p","l":0,"v":"The score is based on five clinical parameters:"},{"k":"p","l":1,"v":"Age ‡ 60 years = 1 point"},{"k":"p","l":1,"v":"Blood Pressure Systolic ‡ 140 mmHg or diastolic ‡ 90 mmHg = 1 point Clinical Features Unilateral weakness = 2 points"},{"k":"p","l":2,"v":"Speech disturbance without weakness = 1 point"},{"k":"p","l":1,"v":"Duration of Symptoms ‡ 60 minutes = 2 points"},{"k":"p","l":2,"v":"10-59 minutes = 1 point"},{"k":"p","l":1,"v":"Diabetes History of diabetes = 1 point"},{"k":"p","l":0,"v":"ABCD2 Score Interpretation:"},{"k":"p","l":1,"v":"< 4 points Low risk of stroke (1% risk of stroke within 2 days)"},{"k":"p","l":1,"v":"4-5 points Moderate risk of stroke (4% risk of stroke within 2 days)"},{"k":"p","l":1,"v":"> 5 points High risk of stroke (8% risk of stroke within 2 days)"},{"k":"p","l":0,"v":"This patient’s ABCD2 score is calculated as follows:"},{"k":"b","l":0,"v":"Age ‡ 60: 1 point"},{"k":"b","l":0,"v":"Blood pressure ‡ 140/90 mmHg: 1 point"},{"k":"b","l":0,"v":"Clinical features (unilateral weakness): 2 points"},{"k":"b","l":0,"v":"Duration (10-59 minutes): 1 point"},{"k":"b","l":0,"v":"Diabetes: 1 point"},{"k":"p","l":0,"v":"Total score = 6 points and high risk."}]},{"n":19,"q":"A 55-year-old man with a history of poorly controlled hypertension presents to the emergency department after suddenly developing a severe headache, vomiting, and one-sided weakness. On examination, he is drowsy with a Glasgow Coma Scale (GCS) of 10. His blood pressure is 220/110 mmHg. CT of the patient is given below. Which of the following is the most likely underlying cause of this patient's hemorrhagic stroke?","o":[{"t":"Ruptured saccular (berry) aneurysm"},{"t":"Charcot-Bouchard microaneurysm rupture"},{"t":"Cerebral venous sinus thrombosis"},{"t":"Arteriovenous malformation (AVM)"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Charcot-Bouchard microaneurysm rupture"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"This patient's presentation of a hemorrhagic stroke, particularly in the basal ganglia (Putamen), is most commonly associated with long-standing hypertension, leading to the rupture of Charcot-Bouchard microaneurysms in small penetrating arteries."},{"k":"p","l":0,"v":"Hemorrhagic stroke"},{"k":"b","l":0,"v":"Hemorrhagic stroke is divided into intracerebral hemorrhage (ICH) and subarachnoid hemorrhage (SAH) . ICH is bleeding into the brain parenchyma, and SAH is bleeding into the subarachnoid space."},{"k":"p","l":0,"v":"Etiology:"},{"k":"p","l":0,"v":"Hypertension is the most common and major cause of hemorrhagic stroke."},{"k":"p","l":1,"v":"Intracerebral hemorrhage (ICH) Subarachnoid"},{"k":"p","l":2,"v":"hemorrhage (SAH)"},{"k":"img","v":7730},{"k":"p","l":1,"v":"Long standing hypertension produces degeneration of media, breakage of the elastic lamina , and fragmentation of smooth muscles of arteries. Charcot-Bouchard aneurysms: Lipohyalinosis, fibrinoid necrosis of the subendothelium, microaneurysms, and focal dilatations are seen in the arterioles. Common sites of hypertension induced intracerebral hemorrhage are the small penetrating arteries originating from basilar arteries or the anterior, middle, or posterior cerebral arteries. Hypertensive change causes non-lobar intracranial hemorrhage (ICH). Beta 40 Cerebral amyloid angiopathy (CAA) is an important cause of primary lobar intracerebral bleeding"},{"k":"p","l":2,"v":"... (content truncated)"},{"k":"p","l":1,"v":"in older adults. Hemorrhage (ICH)\" data-author=\"Jones J, Amer M, Geetha Virupakshappa A\" data-hash=\"9155\" data-license=\"NA\" data-source=\"https://radiopaedia.org/ articles/intracerebral-haemorrhage\" data-tags=\"April2025\" src=\"https://image.prepladder.com /notes/GdlmaOyzTOhhdVKelipJ1744357571.png\" />"},{"k":"p","l":0,"v":"Other causes:"},{"k":"b","l":0,"v":"Cigarette smoking"},{"k":"b","l":0,"v":"Alcohol consumption"},{"k":"b","l":0,"v":"Chronic liver disease"},{"k":"b","l":0,"v":"Dual antiplatelet therapy"},{"k":"b","l":0,"v":"Cocaine, heroin, amphetamine, ephedrine and phenylpropanolamine."},{"k":"b","l":0,"v":"Diabetes mellitus"},{"k":"b","l":0,"v":"Old age and male sex"},{"k":"b","l":0,"v":"Tumors such as glioblastoma, lymphoma, metastasis, meningioma, pituitary adenoma, and"},{"k":"p","l":0,"v":"Pathogenesis:"},{"k":"b","l":0,"v":"The common sites of the bleed are the basal ganglia cerebral lobes, thalamus, pons and the brain stem and the cerebellum."},{"k":"b","l":0,"v":"The hematoma disrupts the neurons and glia."},{"k":"b","l":0,"v":"This results in oligaemia, neuro-transmitter release, mitochondrial dysfunction, and cellular swelling."},{"k":"b","l":0,"v":"Thrombin activates microglia and causes inflammation and edema."},{"k":"b","l":0,"v":"The primary injury is due to the compression of brain tissue by the hematoma and an increase in the intracranial pressure (ICP)."},{"k":"b","l":0,"v":"Secondary injury is contributed to by inflammation, disruption of the blood-brain barrier (BBB) , edema, overproduction of free radicals such as reactive oxygen species (ROS)."},{"k":"b","l":0,"v":"Usually, the hematoma enlarges in 3 hours to 12 hours and lasts up to 14 days."},{"k":"b","l":0,"v":"There is an area of hypoperfusion around the hematoma."},{"k":"b","l":0,"v":"Cerebellar hematoma produces hydrocephalus by compression of the fourth ventricle in the early stage."},{"k":"b","l":0,"v":"Non-aneurysmal spontaneous subarachnoid hemorrhage may be either perimesencephalic or non-perimesencephalic SAH."},{"k":"b","l":0,"v":"In perimesencephalic SAH, bleeding is mainly in the interpeduncular cistern."}],"qi":[7618]},{"n":20,"q":"Which of the following clinical signs of upper motor neuron lesion is described correctly ?","o":[{"t":"Gordon’s sign - A stroke beneath and in front of the lateral malleolus causing an extensor plantar response.Babinski’s sign - Lateral stroke of the sole resulting in flexion of all toes"},{"t":"Gordon’s sign - A stroke beneath and in front of the lateral malleolus causing an extensor plantar response."},{"t":"Oppenheim’s sign - Apply pressure along the medial aspect of tibia causing an extensor plantar response"},{"t":"Chaddock’s sign - Squeeze the calf muscles to produce extensor plantar response."}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Oppenheim’s sign - Apply pressure along the medial aspect of tibia causing an extensor plantar response."},{"k":"h","l":0,"v":"Explanation :"},{"k":"b","l":0,"v":"Oppenheim’s sign is elicited by applying pressure along the medial aspect of tibia to cause an extensor plantar response i.e. dorsiflexion of the great toe and fanning of the other toes. (Option C)"},{"k":"b","l":0,"v":"Babinski’s sign is elicited by stroking the lateral aspect of the sole from the heel towards the little toe and then continuing up to the great toe. This results in an extensor plantar response as described above in a case of upper motor neuron lesion. Flexion of all toes indicates a normal person or the presence of a lower motor neuron lesion. (Option A ruled out)"},{"k":"b","l":0,"v":"Gordon’s sign is elicited by squeezing the calf muscles to produce an extensor plantar response. (Option B ruled out)"},{"k":"p","l":0,"v":"Chaddock’s sign is elicited by stimulating the dorsolateral aspect of the foot from the posterior portion of the skin just beneath the lateral malleolus anteriorly and along the external edge of the foot. (Option D ruled out)"},{"k":"img","v":7734}]},{"n":21,"q":"An elderly patient presented with a history of slowing of movements, frequent falls and forgetfulness. MRI done is as shown below. Which among the following is not a feature of this condition?","o":[{"t":"Defective downward gaze"},{"t":"Bradykinesia and tremors"},{"t":"Poor response to levodopa"},{"t":"Gunslinger’s gait"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Bradykinesia and tremors"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"MRI shows Hummingbird sign - suggestive of Progressive supranuclear palsy [PSP] (a Parkinson-plus disorder). Tremors are not a feature of PSP ."},{"k":"p","l":1,"v":"Progressive supranuclear Early onset postural instability - H/O frequent falls + palsy [PSP] Dementia"},{"k":"p","l":2,"v":"Tremors - absent (Option B) Defective downward gaze (Option A) + extended posture of body Dystonia: Procerus sign (forehead) + Gunslinger’s gait (flexion at elbow & adduction at upper limb) (Option D) Poor response to levodopa (Option C) MRI: Hummingbird sign"},{"k":"p","l":1,"v":"Lewy body dementia [LBD] Parkinsonian features + Visual hallucination + early"},{"k":"p","l":2,"v":"Dementia Associated REM sleep disorder may be present"},{"k":"img","v":7739},{"k":"p","l":1,"v":"Multiple systemic atrophy [MSA]"},{"k":"p","l":2,"v":"MSA-A: Autonomic instability + (orthostatic hypotension) MSA-C: Cerebellar symptoms + ; MRI- Hot cross bun sign (Pons)"},{"k":"p","l":1,"v":"Corticobasal syndrome Dystonia + myoclonus + alien limb phenomena present [CBS] alone with other parkinsonian features"},{"k":"p","l":2,"v":"bun sign\" data-author=\"Moreira, Ana Sofia & Castro, Miguel & Grande, Pablo & Gameiro, Ana & Bahia Soares, Carla & Costa, Yessica & Silva, Luís & Saraiva, José & Dinis, Mónica.\" data-hash=\"9232\" data-license=\"NA\" data-source=\"https://www.researchgat e.net/figure/Hot-Cross-Bun-Sign-Head-T2W-MRI-though- the-pons-showing-a-hyperintense-pontine-cross_fig2_31 4914201\" data-tags=\"April2025\""},{"k":"p","l":2,"v":"YMWmfFSuA1744361572.png\" />"}],"qi":[7624]},{"n":22,"q":"A 62-year-old woman presents with chronic burning pain, numbness, and tingling on the right side of her body not relieved with NSAIDs. The symptoms began 2 months after she suffered a stroke. On examination, she has hyperesthesia and allodynia on the right side. The clinician suspected it to be due to lacunar infarct. What could be the likely site of infarct causing her present symptoms?","o":[{"t":"Ventroposterolateral thalamus"},{"t":"Posterior limb of internal capsule"},{"t":"Genu of internal capsule"},{"t":"Cortical pontocerebellar tract"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) Ventroposterolateral thalamus"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Chronic burning pain not relieved by usual NSAIDs following a stroke is due to lacunar infarct of Ventroposterolateral Thalamus , known as Dejerine-Roussy syndrome (aka) Thalamic pain syndrome ."},{"k":"p","l":0,"v":"Dejerine Roussy syndrome:"},{"k":"p","l":1,"v":"Cause Lacunar infarct of penetrating branches of PCA (P1"},{"k":"p","l":2,"v":"segment)"},{"k":"p","l":1,"v":"Clinical features Hemianesthesia affecting one half of body (initially)"},{"k":"p","l":2,"v":"[Hemisensory loss] Later causing burning pain sensation (during recovery) O/E: Hyperaesthesia, allodynia may be present on the affected side"},{"k":"p","l":1,"v":"Treatment Carbamazepine, Gabapentin, TCAs (Tricyclic"},{"k":"p","l":2,"v":"antidepressants)"},{"k":"p","l":0,"v":"Small vessel stroke:"},{"k":"p","l":1,"v":"Cause Lacunar infarct (affecting"},{"k":"p","l":2,"v":"penetrating branches) secondary to atherosclerotic occlusion/lipohyalino sis"},{"k":"p","l":1,"v":"Risk factors Hypertension: Most common"},{"k":"p","l":2,"v":"Diabetes Atrial fibrillation Smoking Hyperlipidemia"},{"k":"p","l":1,"v":"Sites & manifestations Posterior limb of internal capsule Pure motor"},{"k":"p","l":2,"v":"(Option B) hemiparesis"},{"k":"p","l":1,"v":"Genu of internal capsule Clumsy hand dysarthria lacunar (Option C) syndrome (facial weakness)"},{"k":"p","l":1,"v":"Cortical pontocerebellar I/L ataxia + C/L hemiparesis tract (Option D)"},{"k":"p","l":1,"v":"Ventroposterolateral Dejerine-Roussy syndrome thalamus (Option A)"}]},{"n":23,"q":"A 68-year-old male presents to the emergency department with a sudden onset of right-sided weakness and difficulty speaking. His symptoms resolved within 20 minutes. He has a history of hypertension, hyperlipidemia and smoking. On examination, he is neurologically intact. A CT scan of the brain shows no acute infarction. Which of the following best describes the pathophysiology of this condition?","o":[{"t":"Small intracerebral hemorrhage with rapid clot reabsorption"},{"t":"Embolic occlusion with reperfusion before permanent infarction"},{"t":"Permanent neuronal death without immediate infarction on imaging"},{"t":"Decreased cerebral blood flow due to chronic atherosclerosis"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Embolic occlusion with reperfusion before permanent infarction."},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Transient Ischemic Attack (TIA) is a temporary blockage of blood flow, usually due to a small embolus, which resolves before permanent brain damage occurs."},{"k":"p","l":0,"v":"Transient Ischemic Attack (TIA)"},{"k":"b","l":0,"v":"Defined as a transient episode of neurologic dysfunction due to the focal brain, spinal cord, or retinal ischemia without acute infarction or tissue injury."},{"k":"b","l":0,"v":"A TIA typically lasts less than an hour, more often minutes."},{"k":"b","l":0,"v":"Usually resolves within 24 hours."},{"k":"b","l":0,"v":"Risk is highest in the first 48 hours following a transient ischemic attack."},{"k":"p","l":0,"v":"Etiology:"},{"k":"b","l":0,"v":"Common risk factors for all TIA include diabetes, hypertension, age, smoking, obesity, alcoholism, unhealthy diet, psychosocial stress, and lack of regular physical activity."},{"k":"b","l":0,"v":"A previous history of stroke or TIA will increase substantially the subsequent risk of recurrent stroke or TIA."},{"k":"p","l":0,"v":"Pathophysiology:"},{"k":"p","l":0,"v":"TIA subtypes, classified according to the pathophysiological mechanisms"},{"k":"b","l":0,"v":"Large artery atherothrombosis (M/C): This may be intracranial or extracranial atherothrombosis. The mechanism may be a lack of blood flow distal to the site of arterial stenosis or an artery-to-artery embolism."},{"k":"b","l":0,"v":"Small vessel ischemic diseases: The underlying pathology is either lipohyalinosis or small vessel arteriolosclerosis. The commonest risk factor is hypertension, followed by diabetes and age."},{"k":"b","l":0,"v":"Cardiac embolism: A clot in the cardiac chamber, most commonly in the left atrium , is secondary to atrial fibrillation."},{"k":"b","l":0,"v":"Cryptogenic : This is usually a cortical pattern of ischemia without any identifiable large artery atherothrombosis or cardiac source of emboli. More recently it is often referred to as ESUS (embolic stroke of unknown source)."},{"k":"b","l":0,"v":"Other uncommon causes such as arterial dissection or vasculitis."},{"k":"p","l":0,"v":"ABCD2 Score for TIA (Transient Ischemic Attack): The Risk of Stroke"},{"k":"p","l":1,"v":"Parameter Criteria Points"},{"k":"p","l":1,"v":"Age > 60 years 1 point Blood Pressure BP ‡ 140/90 1 point"},{"k":"p","l":1,"v":"Clinical Features Speech disturbance without 1 point"},{"k":"p","l":2,"v":"weakness"},{"k":"p","l":1,"v":"Unilateral weakness 2 points"},{"k":"p","l":1,"v":"Duration 10–59 minutes 1 point ‡ 60 minutes 2 points"},{"k":"p","l":1,"v":"Diabetes Presence of diabetes 1 point"},{"k":"p","l":0,"v":"Stroke Risk Based on Score:"},{"k":"p","l":0,"v":"Score Stroke Risk"},{"k":"p","l":0,"v":"Day 2 Day 7 Day 90"},{"k":"p","l":0,"v":"0–3 1% 1.2% 3.1%"},{"k":"p","l":0,"v":"4–5 4.1% 5.9% 9.8%"},{"k":"p","l":0,"v":"6–7 8.1% 11.7% 17.8%"}]},{"n":24,"q":"As an intern in the medicine ward, you are asked to guide the nursing staff about the various supportive care measures to improve the outcome of stroke patients. Which among the following will you not advise?","o":[{"t":"Start nasogastric feeding if risk of aspiration is present."},{"t":"Urinary catheterisation is recommended for routine bladder care."},{"t":"Pneumatic compression stockings are indicated to prevent deep vein thrombosis."},{"t":"Give antipyretics to patients with fever to prevent infarct expansion."}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Urinary catheterisation is recommended for routine bladder care."},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Among the given options, urinary catheterisation for routine bladder care is not recommended in stroke patients as it increases the risk of urinary tract infections in these patients, thereby increasing the duration of hospital stay ."},{"k":"p","l":0,"v":"It is recommended only in cases of acute urinary retention or incontinence threatening to pressure areas ."},{"k":"p","l":1,"v":"Supportive measures to improve stroke outcome"},{"k":"p","l":1,"v":"1. Airway Perform bedside screening for dysphagia and keep"},{"k":"p","l":2,"v":"patients nil per oral , if swallowing is unsafe or aspiration occurs."},{"k":"p","l":1,"v":"2.Breathing Check respiratory rate and give oxygen if saturation <"},{"k":"p","l":2,"v":"95%."},{"k":"p","l":1,"v":"3.Circulation Check peripheral perfusion , pulse and blood pressure."},{"k":"p","l":2,"v":"Treat abnormalities with fluid replacement , antiarrhythmics and inotropic drugs as appropriate."},{"k":"p","l":1,"v":"4. Hydration If signs of dehydration, give fluids parenterally or by"},{"k":"p","l":2,"v":"nasogastric tube."},{"k":"p","l":1,"v":"5.Nutrition Assess nutritional status and provide supplements if"},{"k":"p","l":2,"v":"needed. If dysphagia persists for >48 hrs , start feeding via nasogastric tube instead of oral. Consider other routes for essential medications if dysphagia is present."},{"k":"p","l":1,"v":"6.Glycemic control Check blood glucose and treat when levels are ‡ 200"},{"k":"p","l":2,"v":"mg/dl by insulin infusion or glucose/potassium/insulin combination. Monitor closely to avoid hypoglycemia ."},{"k":"p","l":1,"v":"7.Temperature Look for fever, investigate and treat underlying cause"},{"k":"p","l":2,"v":"Control with antipyretics , as raised brain temperature may increase infarct volume. (Option D ruled out)"},{"k":"p","l":1,"v":"8. Infection control Avoid routine catheterisation to prevent UTIs."},{"k":"p","l":2,"v":"Chest physiotherapy to avoid lung infections. Avoid aspiration by nasogastric feeding if required. (Option A ruled out)"},{"k":"p","l":1,"v":"9.Pressure areas Provide pressure-relieving mattresses like water-bed, air"},{"k":"p","l":2,"v":"beds. Pneumatic compression stockings and anticoagulation with heparin to reduce risk of deep vein thrombosis. (Option C ruled out) Regular frequent mobilization of patients along with physiotherapy for immobile joints like shoulders,etc."},{"k":"p","l":1,"v":"10.Bowel and bladder care Check for constipation and urinary retention ; treat these"},{"k":"p","l":2,"v":"appropriately. Avoid urinary catheterisation unless the patient is in acute urinary retention or urinary incontinence is threatening pressure areas . Appropriate dietary changes and stool softeners for constipation."},{"k":"p","l":1,"v":"11.Psychological care Maintain a positive attitude and provide appropriate"},{"k":"p","l":2,"v":"information regarding treatment options and prognosis. Antidepressants and anti-anxiety medications if indicated."}]},{"n":25,"q":"A 70 year old male presents with acute onset right-sided weakness and slurred speech for the past 2 hours. His blood pressure is 180/110 mmHg, and a non-contrast CT scan of the brain shows no evidence of hemorrhage. His medical history includes atrial fibrillation, for which he is on warfarin, and a recent gastrointestinal bleed 10 days ago. Which of the following is a contraindication to thrombolysis with rtPA in this patient?","o":[{"t":"Symptom onset within 2 hours"},{"t":"Blood pressure of 180/110 mmHg"},{"t":"Recent gastrointestinal bleed"},{"t":"Absence of hemorrhage on CT"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Recent gastrointestinal bleed"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"A gastrointestinal bleed within the past 21 days is a clear contraindication to rtPA due to the high risk of rebleeding. In this case, the patient's recent GI bleed 10 days ago makes thrombolysis contraindicated."},{"k":"p","l":1,"v":"Indications and contraindications for thrombolysis"},{"k":"p","l":1,"v":"Indications for rtPA in Acute Clinical Diagnosis of Stroke: The patient presents with Ischemic Stroke (AIS) clinical features of acute stroke, confirmed by a"},{"k":"p","l":2,"v":"neurological examination. No Evidence of Haemorrhage on Imaging : A non-contrast CT scan must exclude hemorrhagic stroke before administering rtPA. (Option D ruled out) Time Window: Administer within 3 hours of symptom onset (FDA); in some regions, the window is extended to 4.5 hours with restrictions. (Option A ruled out) Age : The patient must be 18 years or older."},{"k":"p","l":1,"v":"Contraindications for rtPA in AIS Conditions Increasing Bleeding Risk: Active internal"},{"k":"p","l":2,"v":"bleeding, bleeding diathesis, recent head trauma (within 3 months), recent intracranial hemorrhage, majorsurgery in the last 14 days, gastrointestinal bleeding inthe past 21 days, recent myocardial infarction. (Option C) Uncontrolled Hypertension: Blood pressure >185/110 mmHg despite treatment increases the risk of hemorrhagic complications. (Option B ruled out) Large Infarct Core: CT scan revealing significant edema in more than one-third of the MCA territory is contraindicated due to the risk of hemorrhage and limited benefit."},{"k":"p","l":1,"v":"Additional Points to Consider Use of Antithrombotic Agents: Concomitant use of"},{"k":"p","l":2,"v":"anticoagulants requires careful evaluation to avoid increasing bleeding risk. Advanced Imaging: Techniques like CT perfusion or MRI may help identify patients eligible for rtPA beyond the standard time window, even up to 24 hours in some cases, though this approach remains investigational."}]},{"n":26,"q":"A 68 year old male presents to the emergency department 2 hours after sudden onset of left sided weakness and slurred speech. His blood pressure is 180/100 mmHg, and a non-contrast CT scan shows no hemorrhage. His past medical history includes hypertension and type 2 diabetes and he is not on any anticoagulants. What is the most appropriate initial treatment for this patient?","o":[{"t":"Intravenous recombinant tissue plasminogen activator (rtPA)"},{"t":"Antiplatelet therapy with aspirin"},{"t":"Initiation of anticoagulation therapy"},{"t":"Immediate blood pressure reduction to <140/90 mmHg"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) Intravenous recombinant tissue plasminogen activator (rtPA)"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"rtPA is the first line treatment for acute ischemic stroke if the patient presents within 4.5 hours of symptom onset and there are no contraindications , such as hemorrhage on imaging or high bleeding risk."},{"k":"b","l":0,"v":"This patient is within the time window for rtPA, and his CT shows no hemorrhage, making him a candidate for thrombolysis."},{"k":"b","l":0,"v":"Administering rtPA can significantly improve clinical outcomes by dissolving the clot and restoring blood flow to the brain. Treatment for stroke- ischemic stroke"},{"k":"p","l":1,"v":"Immediate Medical Support Stabilize the patient by managing airway, breathing, and"},{"k":"p","l":2,"v":"circulation (ABCs) . Manage blood pressure : Permissive hypertension is allowed to maintain cerebral perfusion, but reduce BP if >220/120 mmHg ( reduce BP if >185/110 mmHg- for rtPA). Avoid overly aggressive reduction . (Option D ruled out)"},{"k":"p","l":2,"v":"Control fever and hyperglycemia. Treat cerebral edema with mannitol or hemicraniectomy if severe."},{"k":"p","l":1,"v":"Restoring Blood Flow: Intravenous Thrombolysis (rtPA): Effective within 4.5 Thrombolysis & Thrombectomy hours of symptom onset."},{"k":"p","l":2,"v":"Endovascular Thrombectomy: Best for large vessel occlusions, ideally within 6 hours ; can be extended up to 24 hours using advanced imaging."},{"k":"p","l":1,"v":"Preventing Future Strokes Antiplatelet Therapy:"},{"k":"p","l":2,"v":"Aspirin for secondary prevention, delayed 24 hours post-rtPA or given immediately if rtPA not used. (Option B ruled out) Clopidogrel or ticagrelor may be combined with aspirin for short-term use. Anticoagulation: Recommended for atrial fibrillation but avoided in acute stroke unless cardioembolic source is confirmed after rtPA. (Option C ruled out)"},{"k":"p","l":1,"v":"Rehabilitation Early intervention with physical, occupational, and"},{"k":"p","l":2,"v":"speech therapy helps maximize recovery."}]},{"n":27,"q":"A 50 year old male patient came to the emergency room with complaints of headache, blurring of vision, altered sensorium, slurring of speech and left sided hemiparesis for 2 hours. He is a known case of diabetes mellitus, hypertension with irregular compliance. His vitals and CT image are given below. What is the most appropriate statement regarding management of this patient? BP - 190/110 mm Hg PR - 92/min SpO2 - 98%","o":[{"t":"The head end of the patient bed should be flat to prevent coning of the brain."},{"t":"Blood pressure of the patient should be reduced to <140/90 with nicardipine."},{"t":"Immediate intravenous thrombolysis with rtPA is recommended since the patient is in the window period."},{"t":"Heparin should be started immediately to prevent further brain anoxia."}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Blood pressure of the patient should be reduced to <140/90 with nicardipine."},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"The given clinical scenario of a 50 year old male patient with left sided hemiparesis, slurring of speech, signs of raised intracranial pressure (headache, blurring of vision, altered sensorium) for 2 hours and CT brain showing haemorrhage (hyperdense lesion) in the area of left putamen is suggestive of acute hemorrhagic stroke . His history of irregular compliance to hypertension is the likely cause of putaminal haemorrhage in this case."},{"k":"b","l":0,"v":"The appropriate statement regarding management of haemorrhagic stroke in this patient is that the blood pressure of the patient should be reduced to <140/90 with nicardipine . In contrast to ischaemic stroke, the blood pressure should be reduced immediately to <140/90 with non-vasodilating IV drugs such as nicardipine, labetalol, or esmolol to prevent further hematoma expansion . Nimodipine is used to maintain cerebral perfusion in SAH."},{"k":"b","l":0,"v":"Whereas in a case of ischemic stroke, cerebral autoregulation occurs to increase the blood pressure to a higher range to maintain the cerebral perfusion pressure 50–70 mmHg . Hence, the blood pressure should not be reduced until >220/130 mm Hg suggestive of malignant hypertension."},{"k":"p","l":1,"v":"Haemorrhagic stroke"},{"k":"p","l":1,"v":"Etiology Accounts for ~10% of all strokes"},{"k":"p","l":2,"v":"Higher incidence in Asians and blacks. Most common cause - head trauma Other important causes - hypertension, coagulopathy , sympathomimetic drugs ( cocaine, methamphetamine ), and cerebral amyloid angiopathy (CAA). Risk factors: Advanced age, heavy alcohol use, low-dose aspirin in asymptomatic individuals."},{"k":"p","l":1,"v":"Clinical features Abrupt onset of focal neurologic deficit, may worsen"},{"k":"p","l":2,"v":"over 30–90 minutes. Signs of raised intracranial pressure (ICP) such as headache, vomiting, altered sensorium, blurring of vision/diplopia,etc Larger haemorrhages can result in drowsiness, stupor or even coma. Specific presentations based on haemorrhage location: Putamen : ipsilateral hemiparesis , slurred speech. Thalamus : contralateral hemiplegia , sensory deficits, possible aphasia. Pontine : deep coma, quadriplegia , pinpoint pupil s. Cerebellar : occipital headache, ataxia , vomiting. Lobar : focal headaches, varying neurologic deficits depending on the lobe affected."},{"k":"p","l":1,"v":"Investigations CT scan for acute detection of haemorrhage."},{"k":"p","l":2,"v":"Routine blood tests to assess platelet count, prothrombin time, partial thromboplastin time, and international normalized ratio (INR) . MRI may help in identifying underlying causes like arteriovenous malformations (AVMs ). Angiography if etiology is uncertain; lumbar puncture is generally avoided due to risk of herniation."},{"k":"p","l":1,"v":"Treatment Acute Management : Assess airway, breathing and"},{"k":"p","l":2,"v":"control blood pressure . Manage ICP if elevated with elevation of head end of patient bed, administering osmotic agents like mannitol , hypertonic saline , CSF drainage. Correct coagulopathy (e.g., prothrombin complex concentrates for vitamin K antagonists ). Prevention focused on controlling hypertension and avoiding illicit drugs. Surgical intervention for cerebellar haemorrhage >3 cm, or if there is significant deterioration."},{"k":"p","l":0,"v":"Head end of the patient bed should be flat to prevent coning of the brain (Option A): Head end of the patient bed should be elevated as a measure to reduce the raised intracranial pressure. Flattening the head end of the bed does not prevent coning ."},{"k":"p","l":0,"v":"Immediate intravenous thrombolysis with rtPA is recommended since the patient is in the window period (Option C): Intravenous thrombolysis is indicated in the case of ischaemic stroke and not haemorrhagic stroke."},{"k":"p","l":0,"v":"Heparin should be started immediately to prevent further brain anoxia (Option D): Heparin is also not indicated in the case of hemorrhagic stroke as it can cause further expansion of the hematoma and usually given only after 24 hours of thrombolysis or mechanical thrombectomy in the case of ischaemic stroke ."}],"qi":[7633]},{"n":28,"q":"A 62-year-old right-handed male is brought to the emergency department with sudden onset of right-sided weakness and difficulty speaking. On examination, he has weakness in the right arm and face, with mild weakness in the right leg. He is also unable to speak fluently but can understand spoken language. His gaze is deviated to the left, and he has a right homonymous hemianopia. Which of the following is the most likely location of the thrombus causing this patient's symptoms?","o":[{"t":"Anterior Cerebral Artery (ACA) thrombosis"},{"t":"Middle Cerebral Artery (MCA) thrombosis"},{"t":"Posterior Cerebral Artery (PCA) thrombosis"},{"t":"Basilar Artery thrombosis"}],"a":[1],"s":[{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"The patient presents with contralateral (right-sided) weakness, more prominent in the arm and face, aphasia (difficulty speaking), gaze deviation, and homonymous hemianopia - all classic features of an MCA stroke , typically affecting the dominant hemisphere."},{"k":"p","l":0,"v":"Stroke clinical features based on the location of the thrombus:"},{"k":"p","l":1,"v":"Location Clinical Features"},{"k":"p","l":1,"v":"Middle Cerebral Artery (MCA) Most common artery involved in stroke. Thrombosis Contralateral hemiparesis and hemisensory loss: More"},{"k":"p","l":2,"v":"prominent in the face and upper limb than the lower limb. Dysarthria caused by both dominant and non dominant hemispheres. Broca’s aphasia (expressive) in the superior division infarct. Wernicke’s aphasia (receptive) in the inferior division infarct. Neglect Homonymous hemianopia : Loss of vision in the same visual field of both eyes. Gaze preference towards the side of the lesion."},{"k":"p","l":1,"v":"Anterior Cerebral Artery Contralateral hemiparesis and sensory loss: More (ACA) Thrombosis pronounced in the lower limb than the upper limb."},{"k":"p","l":2,"v":"Urinary incontinence: Due to involvement of the medial frontal micturition centers. Behavioral or personality changes: Due to involvement of the prefrontal cortex (apathy, disinhibition). Abulia (lack of will) and apraxia. Upper extremity and face are spared."},{"k":"p","l":1,"v":"Posterior Cerebral Artery Contralateral homonymous hemianopia with macular (PCA) Thrombosis sparing (due to collateral blood supply from MCA)."},{"k":"p","l":2,"v":"Visual agnosia (inability to recognize objects). Alexia without agraphia: Inability to read without difficulty writing (if the dominant hemisphere is involved). Contralateral sensory loss or thalamic pain syndrome: Due to infarction in the thalamus (Dejerine-Roussy syndrome). Memory impairment: If the temporal lobe is affected."},{"k":"p","l":1,"v":"Vertebrobasilar Artery The clinical presentation includes ataxia, vertigo, Thrombosis headache, vomiting, oropharyngeal dysfunction, visual"},{"k":"p","l":2,"v":"field deficits, and abnormal oculomotor findings. Patterns of clinical presentation vary depending on the location and the infarction pattern of embolism or atherosclerosis."},{"k":"p","l":1,"v":"Cerebellar Infarction Patients may present with ataxia, nausea, vomiting,"},{"k":"p","l":2,"v":"headache, dysarthria, and vertigo symptoms."},{"k":"p","l":1,"v":"Lacunar Infarction Lacunar infarcts result from the occlusion of small"},{"k":"p","l":2,"v":"perforating or penetrating arteries. Infarcts are smaller than 1 centimeter in diameter. Present with a pure motor or sensory loss, sensorimotor deficit or ataxic-hemiparesis."}]},{"n":29,"q":"In patients presenting with acute ischemic stroke, MRI or CT imaging of a lesion greater than which size is most indicative of a stroke due to large artery atherosclerotic origin?","o":[{"t":"> 2.0 cm"},{"t":"> 2.5 cm"},{"t":"> 3.0 cm"},{"t":"> 1.5 cm"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) > 1.5 cm"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"Strokes of large artery atherosclerotic origin are typically associated with lesions larger than 1.5 cm on MRI or CT imaging. Lesions of this size suggest involvement of large vessels, while smaller lesions are more often related to lacunar infarcts."},{"k":"p","l":0,"v":"Acute Ischemic stroke"},{"k":"b","l":0,"v":"Acute stroke is the acute onset of focal neurological deficits in a vascular territory affecting the brain, retina, or spinal cord due to underlying cerebrovascular diseases."},{"k":"p","l":0,"v":"Etiology:"},{"k":"b","l":0,"v":"The etiology of ischemic stroke is a thrombotic or embolic event that causes an impairment of blood flow to an area of the brain."},{"k":"b","l":0,"v":"In a thrombotic event , the blood flow to the brain is obstructed within the blood vessel due to a thrombus within the vessel itself, usually secondary to atherosclerotic disease, arterial dissection, fibromuscular dysplasia."},{"k":"b","l":0,"v":"In an embolic event, debris from elsewhere in the body blocks blood flow through the affected vessel."},{"k":"b","l":0,"v":"The source of emboli can be the proximal artery, such as an atherosclerotic plaque in the internal carotid artery, causing an artery-to-artery embolic stroke distally from any proximal source, commonly from the heart."},{"k":"p","l":1,"v":"Cardioembolism Comprises patients with arterial blockages likely caused"},{"k":"p","l":2,"v":"by an embolism originating in the heart. At least 1 cardiac source of an embolus must be identified to consider a possible or probable diagnosis of cardioembolic stroke. Evidence of a previous transient ischemic attack (TIA) or stroke in more than 1 vascular territory or systemic embolisms supports a clinical diagnosis of cardiogenic stroke. A stroke occurring in a patient with a medium-risk cardiac source of embolism and no other apparent cause of stroke is categorized as a possible cardioembolic stroke."},{"k":"p","l":1,"v":"Large artery atherosclero Patients will exhibit clinical and brain imaging findings sis indicating either significant (> 50%) narrowing or"},{"k":"p","l":2,"v":"complete blockage of a major brain artery or branch cortical artery, likely due to atherosclerosis. Presence of intermittent claudication history, TIAs in the same vascular territory, a carotid bruit, or weakened pulses. Lesions in the cortex, cerebellum, brainstem, or subcortical hemispheric infarctions > 1.5 cm in diameter observed on CT or MRI indicate potential large artery atherosclerotic origin. Duplex imaging or arteriography demonstrating more than 50% stenosis of a relevant intracranial or extracranial artery is necessary ."},{"k":"p","l":1,"v":"Small vessel occlusion Patients with strokes commonly classified as lacunar"},{"k":"p","l":2,"v":"infarcts in other systems. Patients should present with 1 of the typical clinical lacunar syndromes and should not exhibit signs of cerebral cortical dysfunction. Patients should have normal CT scan or MRI findings Brainstem or subcortical hemisphere lesion with a diameter of <1.5 cm."},{"k":"p","l":1,"v":"Stroke of undetermined Patient with atrial fibrillation and ipsilateral carotid etiology stenosis of 50%."},{"k":"p","l":2,"v":"Traditional lacunar syndrome and ipsilateral carotid stenosis of 50%."},{"k":"p","l":1,"v":"Stroke of other Patients with uncommon stroke causes, such as determined etiology nonatherosclerotic vasculopathies, hypercoagulable"},{"k":"p","l":2,"v":"states, or hematologic disorders. Patients in this category should exhibit clinical symptoms and CT or MRI findings indicative of acute ischemic stroke, regardless of the size or location of the lesion. Diagnostic tests, such as blood tests or arteriography, should reveal 1 of these unusual stroke causes."}]}]);
QB.imgs({"7553":"data:image/jpeg;base64,","7681":"data:image/jpeg;base64,","7685":"data:image/jpeg;base64,","7559":"data:image/jpeg;base64,","7691":"data:image/jpeg;base64,","7565":"data:image/jpeg;base64,","7697":"data:image/jpeg;base64,","7571":"data:image/jpeg;base64,","7702":"data:image/jpeg;base64,","7576":"data:image/jpeg;base64,","7707":"data:image/jpeg;base64,","7582":"data:image/jpeg;base64,","7713":"data:image/jpeg;base64,","7588":"data:image/jpeg;base64,","7594":"data:image/jpeg;base64,","7599":"data:image/jpeg;base64,","7730":"data:image/jpeg;base64,","7606":"data:image/jpeg;base64,","7734":"data:image/jpeg;base64,","7739":"data:image/jpeg;base64,","7612":"data:image/jpeg;base64,","7618":"data:image/jpeg;base64,","7624":"data:image/jpeg;base64,","7633":"data:image/jpeg;base64,","7642":"data:image/jpeg;base64,","7676":"data:image/jpeg;base64,","7648":"data:image/jpeg;base64,","7654":"data:image/jpeg;base64,","7659":"data:image/jpeg;base64,","7664":"data:image/jpeg;base64,","7542":"data:image/jpeg;base64,","7671":"data:image/jpeg;base64,","7548":"data:image/jpeg;base64,"});